Q(234,4,"Access reviews","Pelo dump, User3 e User5 podem criar a revisão do Package1 — conforme as funções da tabela do caso (Identity Governance administrator, Catalog owner ou Access package manager do catálogo). Confira a tabela do caso.", g=("case","LITWARE"), r="duvidosa")
